#pragma once
class Block39_1080Pass {
public:
 void Create(ID3D12Device*d,ID3D12Resource*main,ID3D12Resource*skip,ID3D12Resource*raw,ID3D12Resource*bias,ID3D12Resource*combined,ID3D12Resource*output){const char*s=R"(StructuredBuffer<float> mainInput:register(t0);ByteAddressBuffer skipInput:register(t1),raw:register(t2);StructuredBuffer<float> bias:register(t3);RWByteAddressBuffer combined:register(u0),output:register(u1);float H(ByteAddressBuffer b,uint i){uint x=b.Load((i&~1)*2);return f16tof32((x>>((i&1)*16))&65535);}[numthreads(64,1,1)]void pack(uint3 id:SV_DispatchThreadID){uint i=id.x*2;if(i>=2040*1536)return;float v[2];[unroll]for(uint z=0;z<2;z++){uint n=i+z,p=n/1536,c=n%1536,x=p%60,y=p/60;if(c<1024)v[z]=mainInput[((y/2)*30+x/2)*1024+c];else v[z]=H(skipInput,(y*64+x)*512+c-1024);}combined.Store(i*2,f32tof16(v[0])|(f32tof16(v[1])<<16));}[numthreads(64,1,1)]void finish(uint3 id:SV_DispatchThreadID){uint i=id.x*2;if(i>=40*64*512)return;float v[2];[unroll]for(uint z=0;z<2;z++){uint n=i+z,p=n/512,c=n%512,x=p%64,y=p/64;v[z]=(y>=34||x>=60)?0:H(raw,(y*60+x)*512+c)+bias[c];}output.Store(i*2,f32tof16(v[0])|(f32tof16(v[1])<<16));})";const char*en[]={"pack","finish"};ID3DBlob*code[2]{},*error=nullptr;for(UINT i=0;i<2;i++)dmlrt_check("block39 compile",D3DCompile(s,std::strlen(s),nullptr,nullptr,nullptr,en[i],"cs_5_1",D3DCOMPILE_OPTIMIZATION_LEVEL3,0,&code[i],&error));D3D12_DESCRIPTOR_RANGE ranges[2]={{D3D12_DESCRIPTOR_RANGE_TYPE_SRV,4,0,0,0},{D3D12_DESCRIPTOR_RANGE_TYPE_UAV,2,0,0,4}};D3D12_ROOT_PARAMETER p{};p.ParameterType=D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;p.DescriptorTable={2,ranges};D3D12_ROOT_SIGNATURE_DESC rd{};rd.NumParameters=1;rd.pParameters=&p;ID3DBlob*sig=nullptr;dmlrt_check("block39 signature",D3D12SerializeRootSignature(&rd,D3D_ROOT_SIGNATURE_VERSION_1,&sig,&error));dmlrt_check("block39 root",d->CreateRootSignature(0,sig->GetBufferPointer(),sig->GetBufferSize(),IID_PPV_ARGS(&root_)));for(UINT i=0;i<2;i++){D3D12_COMPUTE_PIPELINE_STATE_DESC pd{};pd.pRootSignature=root_;pd.CS={code[i]->GetBufferPointer(),code[i]->GetBufferSize()};dmlrt_check("block39 pso",d->CreateComputePipelineState(&pd,IID_PPV_ARGS(&pso_[i])));}D3D12_DESCRIPTOR_HEAP_DESC hd{D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV,6,D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE,0};dmlrt_check("block39 heap",d->CreateDescriptorHeap(&hd,IID_PPV_ARGS(&heap_)));UINT step=d->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);auto cpu=heap_->GetCPUDescriptorHandleForHeapStart();D3D12_SHADER_RESOURCE_VIEW_DESC sv{};sv.ViewDimension=D3D12_SRV_DIMENSION_BUFFER;sv.Shader4ComponentMapping=D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;sv.Buffer.StructureByteStride=4;sv.Buffer.NumElements=18*30*1024;d->CreateShaderResourceView(main,&sv,cpu);cpu.ptr+=step;sv.Format=DXGI_FORMAT_R32_TYPELESS;sv.Buffer.StructureByteStride=0;sv.Buffer.Flags=D3D12_BUFFER_SRV_FLAG_RAW;for(auto x:{std::pair<ID3D12Resource*,UINT>{skip,40*64*512/2},{raw,2040*512/2}}){sv.Buffer.NumElements=x.second;d->CreateShaderResourceView(x.first,&sv,cpu);cpu.ptr+=step;}sv.Format=DXGI_FORMAT_UNKNOWN;sv.Buffer.Flags=D3D12_BUFFER_SRV_FLAG_NONE;sv.Buffer.StructureByteStride=4;sv.Buffer.NumElements=512;d->CreateShaderResourceView(bias,&sv,cpu);cpu.ptr+=step;D3D12_UNORDERED_ACCESS_VIEW_DESC uv{};uv.ViewDimension=D3D12_UAV_DIMENSION_BUFFER;uv.Format=DXGI_FORMAT_R32_TYPELESS;uv.Buffer.Flags=D3D12_BUFFER_UAV_FLAG_RAW;uv.Buffer.NumElements=2040*1536/2;d->CreateUnorderedAccessView(combined,nullptr,&uv,cpu);cpu.ptr+=step;uv.Buffer.NumElements=40*64*512/2;d->CreateUnorderedAccessView(output,nullptr,&uv,cpu);}
 void Record(ID3D12GraphicsCommandList*c,UINT which){ID3D12DescriptorHeap*h[]={heap_};c->SetDescriptorHeaps(1,h);c->SetComputeRootSignature(root_);c->SetComputeRootDescriptorTable(0,heap_->GetGPUDescriptorHandleForHeapStart());c->SetPipelineState(pso_[which]);UINT n=which?40*64*512/2:2040*1536/2;c->Dispatch((n+63)/64,1,1);}
private:ID3D12RootSignature*root_{};ID3D12PipelineState*pso_[2]{};ID3D12DescriptorHeap*heap_{};
};
